def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Locate the rectangular frame.
    frame = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 5]
    r0 = min(r for r, c in frame)
    r1 = max(r for r, c in frame)
    c0 = min(c for r, c in frame)
    c1 = max(c for r, c in frame)

    # Read the colored markers at the four outer corners.
    markers = {}
    for corner, (r, c) in {
        "tl": (r0 - 1, c0 - 1), "tr": (r0 - 1, c1 + 1),
        "bl": (r1 + 1, c0 - 1), "br": (r1 + 1, c1 + 1)
    }.items():
        if 0 <= r < h and 0 <= c < w and g[r][c] != 0:
            markers[corner] = g[r][c]

    # Each marker colors its corresponding quadrant; the other diagonal
    # receives the opposite marker color.
    if "tl" in markers and "tr" in markers:
        colors = {"tl": markers["tl"], "tr": markers["tr"],
                  "bl": markers["tr"], "br": markers["tl"]}
    else:
        colors = {"bl": markers["bl"], "br": markers["br"],
                  "tl": markers["br"], "tr": markers["bl"]}

    rm = (r0 + r1) // 2
    cm = (c0 + c1) // 2
    for r in range(r0 + 1, r1):
        for c in range(c0 + 1, c1):
            quadrant = ("t" if r <= rm else "b") + ("l" if c <= cm else "r")
            g[r][c] = colors[quadrant]
    return g
